const historial = $input.all().map(item => item.json);

return [{
  json: {
    historial_texto: JSON.stringify(historial)
  }
}];

conditions.leftValue:
={{ 
  !/no-?reply|do-?not-?reply|mailer-daemon|postmaster/i.test($json.from?.value?.[0]?.address || '') &&
  !/automatic reply|auto.?reply|out of office|fuera de oficina|undeliverable|delivery status notification|delivery failure/i.test($json.subject || '') &&
  !/auto-generated|auto-replied/i.test($json.headers?.['auto-submitted'] || '') &&
  !($json.headers?.['x-autoreply'] || $json.headers?.['x-autorespond'])
}}
